def gold_facts(item, ents):
    """The item's facts with names replaced by prepare()'s placeholders."""
    by = {e['text'].lower(): e['id'] for e in ents}
    descs = [e for e in ents if e['kind'] == 'desc']
    out = []
    for t in item['facts'].split():
        if t.startswith('~'):
            m = next((e['id'] for e in descs if e['text'].lower().split()[-1] == t[1:]), None)
            out.append(m or t)
        elif t.lower() in by and t not in (';',):
            out.append(by[t.lower()])
        else:
            out.append(t)
    return ' '.join(out)
